function CatHouseRegisterCell:FreshUI(rallySignupData, rallyId, maxSignUpNum)
    ----------------------------
    --- 数据处理
    local status = self:InitStatus(rallySignupData, rallyId, maxSignUpNum)
    if self.status == status then
        if status == Status.Registering then
            self:FreshCountdown()
        end
        return
    end
    self.data    = rallySignupData
    self.rallyId = rallyId
    self.status  = status
    self.maxSignUpNum = maxSignUpNum

    ----------------------------
    --- UI显示
    self:ShowUI()

end

function CatHouseRegisterCell:InitStatus(rallySignupData, rallyId, maxSignUpNum)
    local status = Status.Lock
    local nextUnlockDeliveryNum = maxSignUpNum + 1
    if rallyId < nextUnlockDeliveryNum then
        --- 登记后被使用 就是配对成功 这时能领取奖励
        if rallySignupData then
            if checkNumber(rallySignupData.asked) == 1 then
                status = Status.MateSuccess
            else
                local isTimeEnd   = checkNumber(rallySignupData.remainTime) == 0
                local playerCatId = checkNumber(rallySignupData.playerCatId)
                status = isTimeEnd and (playerCatId > 0 and Status.RegisterTimeEnd or Status.CanSignUp) or Status.Registering
            end

        end
    elseif rallyId == nextUnlockDeliveryNum then
        status = Status.CanUnlock
    end
    return status
end

