--- FreshCatStatus1
--- 刷新 第一大类状态 配对成功 登记中 登记结束
function CatHouseRegisterCell:FreshCatStatus1(isMateSuccess, isRegistering, isRegisterTimeEnd)
    local status            = self.status

    --------------------------
    --- 刷新 标题
    self.TitleStatusImgIcon.Status = isMateSuccess and 1 or 2
    local t = {
        [Status.MateSuccess] = 1,
        [Status.Registering] = 2,
        [Status.RegisterTimeEnd] = 3,

    }
    self.TextStatus.Status = t[status]

    ---@type CatHouseComponent
    local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
    local catData
    if not isMateSuccess then
        catData = component:GetCatDataById(self.data.playerCatId)
        self.TxtCatName.text = catData.name
    end
    KTool.SetActive(self.Imgbg2.gameObject, not isMateSuccess)
    KTool.SetActive(self.TxtCatName.gameObject, not isMateSuccess)

    --------------------------
    --- 刷新 配对成功相关
    KTool.SetActive(self.ImgGold.gameObject, isMateSuccess)

    local isShowCat = isRegistering or isRegisterTimeEnd
    KTool.SetActive(self.StatusCatIcon.gameObject, isShowCat)
    KTool.SetActive(self.TextCountdown.gameObject, isShowCat)
    if isShowCat then
        local age = catData.age
        self.ImgCatShadow.Status = age
        local isIncubation = checkTable(component:GetCDDataById(self.data.playerCatId))[ConstantsCatHouse.CatStatus.Hatching] ~= nil
        local catHouseMgr = CatHouseMgr:GetInstance()
        if isIncubation then
            self.fileNameId = nil
        else
            local attributes = catHouseMgr:GetAttributes(catData.genes)
            self.fileNameId = catHouseMgr:GetFileNameId(age, catData.catId, attributes)    
            catHouseMgr:CaptureTexture(age, catData.catId, attributes, false, self.fileNameId)
        end
        -- self.fileNameId = (not isIncubation) and catHouseMgr:CaptureTexture(age, catData.catId, catHouseMgr:GetAttributes(catData.genes)) or nil
        
        self:FreshCountdown()
    end

    -- KTool.SetActive(self.FontStyleButton.gameObject, isMateSuccess or isRegistering or isRegisterTimeEnd)
    local isShowBottomContent = isMateSuccess or isRegistering
    KTool.SetActive(self.BottomContent.gameObject, isShowBottomContent)
    if isShowBottomContent then
        local rallyGoodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallyGoodsId).num)
        ---@type GoodsVo
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(rallyGoodsId)
        self.ImgIcon:LoadSprite(goodsVo.photoPath)

        self.TextNumber.text = self.data.price
    end

    self:FreshButtonStatus(status)

end


function CatHouseRegisterCell:FreshButtonStatus(status)
    local config        = Status2Config[status]
    if config == nil then
        return
    end
    local styleId, text = SafeUnpack(config)
    self.FontStyleButton:ResetFontStyle(styleId, text)
end

