function CatHouseRegisterCell:ShowCanSignUpEffect()
    if not isNull(self.effectGo) then
        KTool.SetActive(self.effectGo.gameObject, true)
        return
    end
    local parent = self.controller.gameObject
    local go     = GameUtils.LoadBundleSync(EffectPath, parent)
    self.effectGo = go
end


function CatHouseRegisterCell:FreshCountdown()
