end

function CatHouseRegisterCell:RequestRallySignupCancel()
    local rallyId  = self.rallyId
    GameUtils.Request(Interfaces.CatHouseRallySignupCancel, {
        rallyId = rallyId,
    }, function (request, response)

        ------------------------
        --- 1.处理数据
        --- 1.1  更新奖励
        --local rewards = response.data.rewards
        --GoodsUtils.DrawRewards(rewards)

        --- 1.2 移除倒计时相关数据
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        component:UpdateCDData(self.data.playerCatId, ConstantsCatHouse.CatStatus.Signup)

        --- 1.3 移除 rallySignupList 数据
        self.data = component:ClearRallySignupDataById(rallyId)

        --- 1.4 更新本地数据
        self.status = Status.CanSignUp

        --- 1.5 更新红点
        component:UpdateRallySignupRedPoint()
        ------------------------
        --- 2. 刷新UI
        self:ShowUI()

        -------------------------------
        ---3. 弹出提示
        GameUtils.Toast(localize("已取消登记"))

        -------------------------------
        ---4. 弹出奖励
        --UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
    end)
end

function CatHouseRegisterCell:RequestRallyDraw()
    local rallyId  = self.rallyId
    GameUtils.Request(Interfaces.CatHouseRallyDraw, {
        rallyId = rallyId,
    }, function (request, response)

        ------------------------
        --- 1.处理数据
        --- 1.1  更新奖励
        local rewards = response.data.rewards
        GoodsUtils.DrawRewards(rewards)

        --- 1.2 移除倒计时相关数据
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        -- local playerCatId = self.data.playerCatId
        -- component:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Signup)

        ---1.3 将配对的猫变为 恢复状态
        -- local remainTime = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.HatchRecoverSeconds).num)
        -- component:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Recovering, remainTime)

        --- 1.4 移除 rallySignupList 数据
        self.data   = component:ClearRallySignupDataById(rallyId)

        --- 1.5 更新本地数据
        self.status = Status.CanSignUp

        --- 1.6 更新红点
        component:UpdateRallySignupRedPoint()
        ------------------------
        --- 2. 刷新UI
        self:ShowUI()

        -------------------------------
        ---3. 弹出奖励
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })

    end)
end

function CatHouseRegisterCell:RequestUnlockRallySignUpLimit(consume)
    --- 发送解锁请求解锁
    GameUtils.Request(Interfaces.CatHouseUnlockRallySignUpLimit, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        GoodsUtils.DrawRewards(consume)

        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)

        ------------------------
        --- 1.处理数据
        --- 1.1 更新最大登记数量
        ---@type CatHouseHomeDojo
        local catHouseHomeDojo = component:GetCatHouseHomeDojo()
        local rallyId = checkNumber(catHouseHomeDojo.maxSignUpNum) + 1
        catHouseHomeDojo:FillFieldData("maxSignUpNum", rallyId)
        component:AddRallySignupData({ rallyId = rallyId, remainTime = 0, asked = 0 })

        --- 1.2 更新本地数据
        self.data   = nil
        self.status = Status.CanSignUp
        -------------------------------------
        ---更新UI
        self:ShowUI()
    end)
end



