function CatHouseRegisterCell:OnClickCatStatusAction()
    local status = self.status
    if status == Status.CanSignUp then
        CatHouseMgr:GetInstance():ShowCatListDialogByActionLimit(ConstantsCatHouse.CatActionType.RallySignup,
                ConstantsCatHouse.CatListType.Signup,
                {
                    {id = Constants.UITypeIds.CatHouseRegisterPopup}
                }, {rallyId = self.rallyId}
        )

    elseif status == Status.CanUnlock then
        --- 集会登记位每次扩充消耗道具id
        local goodsId          = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallySignupExpansionConsumeId).num)
        --- 集会登记位每次扩充消耗道具数量
        local num              = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallySignupExpansionConsumeNum).num)
        ---@type GoodsVo
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        GameUtils.SecondConfirm(localize("是否花费_num__name_解锁", {_num_ = num, _name_ = goodsVo.name}), function()
            --- 1. 检查道具消耗
            local consume, errTip = GoodsUtils.CheckGoodConsume({ { goodsId = goodsId, goodsNum = num } })
            if errTip then
                GameUtils.Toast(errTip)
                return
            end
            --- 2. 发送 解锁请求
            self:RequestUnlockRallySignUpLimit(consume)
        end)

    elseif status == Status.Lock then
        GameUtils.Toast(localize("该登记位置未解锁"))

    end

end

function CatHouseRegisterCell:OnClickBtnAction()
    local status = self.status

    if status == Status.MateSuccess then
        self:RequestRallyDraw()
    elseif status == Status.Registering or status == Status.RegisterTimeEnd then
        self:RequestRallySignupCancel()

    end

end

function CatHouseRegisterCell:OnEventCatHouseTimeChange()
    self:FreshUI(self.data, self.rallyId, self.maxSignUpNum)
    if self.data.remainTime <= 0 then
        self:RemoveListener()
    end
end

function CatHouseRegisterCell:OnEventCaptureTextureCompleteAction(id, path)
    if self.fileNameId ~= id then return end
    local texture = CatHouseMgr:GetInstance():LoadCaptureTexture(path)
    self.ImgIconCat.texture = texture
end

